    title: "गोपनीयता नीति",
    updated: "अंतिम बदलाव 14 सितंबर 2026।",
    intro: "Relay स्कूल का हाज़िरी, अंकों, असाइनमेंट और संदेशों का रिकॉर्ड रखता है, और उसे केवल उन्हीं लोगों को दिखाता है जिन्हें स्कूल अनुमति देता है: स्कूल का स्टाफ़, हर बच्चे के अभिभावक और स्वयं बच्चा। इस पृष्ठ पर लिखा है कि क्या रखा जाता है, कौन देख सकता है, वह कहाँ जाता है और आप क्या माँग सकते हैं। यह अभिभावकों के लिए लिखा गया है; जो यहाँ न मिले, वह स्कूल का कार्यालय बता सकता है।",
    s1Title: "डेटा की ज़िम्मेदारी स्कूल की है",
    s1a: "किसी विद्यार्थी का हर रिकॉर्ड एक ही स्कूल का होता है। स्कूल खाता बनाता है, या वह कोड जारी करता है जिससे खाता बनता है, और तय करता है कि उसका कौन-सा स्टाफ़ क्या देख सकता है। भारत के डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम 2023 के अनुसार स्कूल डेटा फ़िड्यूशियरी है, और 18 वर्ष से कम आयु का हर व्यक्ति बच्चा है।",
    s1b: "Relay का सर्वर जो भी चलाता है, वह स्कूल के लिए प्रोसेसर के रूप में काम करता है। ऑपरेटर स्कूलों और निमंत्रणों की सूची देख सकता है, और स्कूल के भीतर कुछ भी नहीं: न हाज़िरी, न अंक, न संदेश। स्कूल के भीतर कोई भी झाँक समय-सीमित होती है, कारण के साथ दर्ज होती है, और उस स्कूल को उसके सुरक्षा केंद्र में दिखाई देती है।",
