    s2Intro: "केवल वही जो स्कूल चलाने के लिए ज़रूरी है:",
    i1: "पहचान: नाम, पसंदीदा नाम, लॉगिन नाम या ईमेल, चुना हुआ अवतार या अपलोड की गई तस्वीर, और एक छोटा परिचय।",
