    i6: "स्टाफ़ के साथ संदेश, बुलेटिन की पोस्ट और टिप्पणियाँ, अभ्यास की प्रगति, प्रतियोगिता की प्रविष्टियाँ, मीटिंग की बुकिंग, शिक्षकों के बारे में प्रतिक्रिया, और जहाँ अभिभावक ने सहमति दी हो वहाँ बाहरी मेंटर के साथ संदेश।",
    i7: "स्कूल छोड़ने के बाद विद्यार्थी के पास रहने वाला रिकॉर्ड।",
    i8: "सूचनाएँ, और उन्हें फ़ोन तक पहुँचाने के लिए ज़रूरी टोकन और फ़ोन का मॉडल।",
    i9: "हर साइन-इन: कब, नेटवर्क का पता और ब्राउज़र या ऐप का संस्करण। साइन-इन लिंक और कोड, जो एक ही बार चलते हैं।",
    i10: "किसने क्या किया और किस नेटवर्क पते से, इसका ऑडिट लॉग, जिसमें सुरक्षा रिपोर्टें और ऐप से भेजी गई समस्या या क्रैश रिपोर्टें शामिल हैं।",
    i11: "पसंद: भाषा, रूप-रंग, सूचना के माध्यम और शांत घंटे।",
    s3Title: "कौन देख सकता है",
    s3a: "स्कूल का स्टाफ़ स्कूल के विद्यार्थियों को देखता है; शिक्षक केवल उन्हीं विद्यार्थियों को देखता है जिनकी कक्षा वह पढ़ाता है। कार्यालय पूरी निर्देशिका देखता है।",
