    s3d: "स्कूल के बाहर कोई भी विद्यार्थी का डेटा नहीं देखता। बाहरी मेंटर विद्यार्थी से तभी संदेश करता है जब अभिभावक ने सहमति दी हो, और प्रतियोगिता की प्रविष्टि भी उसी सहमति से ही स्कूल से बाहर जाती है।",
    s4Title: "Relay क्या नहीं करता",
    s4a: "न विज्ञापन, न एनालिटिक्स, न ट्रैकिंग, न व्यवहार की प्रोफ़ाइलिंग, और किसी और के उद्देश्य के लिए डेटा न बेचा जाता है न साझा किया जाता है।",
